column18:
if(style choice = Keto) then override Protein(Lower Limit & Upper limit)
KetoProtein lower limit = (.15*goal calories)/4 
KetoProtein upper limit = (.25*goal calories)/4

else if(style choice = Fatty Protein) then override Protein(Lower Limit & Upper limit)
&Protein = LBM*ActivityLvl

else select Protein in range (Lower limit<=Protein<=Upper limit)

if(style choice = Keto) then override Fat(Lower Limit & Upper limit)
KetoFat lower limit = (Goal calories - (Protein lower limit*4) - 50)/4
KetoFat lower limit = (Goal calories - (Protein Upper limit*4) - 50)/4

if(style choice = Fatty Protein) then override Fat(Lower Limit & Upper limit)
HPHF Fat lower limit = (LBM*Activity level) & HPHF Fat Upper limit = (LBM*Activity level)+50

if(style choice = Low Carb)
then LowCarb Fat range = 
((Goal calories-((Protein lower limit)/4)-100)/9)<=Low Carb Fat range<= ((Goal calories-((Protein higher limit)/4)-100)/9)


if(style choice = Moderation)
then Moderation Fat range = 
((Goal calories-((Protein lower limit)/4)-100)/9)<=Moderation Fat range<= ((Goal calories-((Protein higher limit)/4)-100)/9)

column10:
if(Style choice = Fatty protein)
then RMR = NA
else RMR = 500+(22*LBM)

column12:
if (style choice = Fatty protein )
then (Goal calories = NA)
else((
if(goal=Lose Fat, then (TDEE-500)
else if(goal=Gain LBM, then (TDEE+500)
else if(goal=maint performance, then(TDEE)))

if Style choice = (Fatty Protein)
then Daily Carb <=30 g 
if Style choice = (Low Carb)
then Daily Carb <=100 g 
if Style choice = (Keto)
then Daily Carb <=50 g

